import{z as i,x as s,o as A,c as d,q as r,j as o,D as t,d as a,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"监管资本的理论","description":"","frontmatter":{"title":"监管资本的理论","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bm-regulatory-capital.md","filePath":"econ/bm-regulatory-capital.md","lastUpdated":1791413859000}'),p={name:"econ/bm-regulatory-capital.md"};function m(C,E,c,h,D,g){const B=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="监管资本的理论" tabindex="-1">监管资本的理论 <a class="header-anchor" href="#监管资本的理论" aria-label="Permalink to &quot;监管资本的理论&quot;">​</a></h1><div class="epigraph"><p>资本是给安全网定价的方式：保险与最后贷款人把挤兑从价格里拿走，资本把亏损的顺序写回合同里。</p><footer>—— 据 Holmström–Tirole 1997、Admati–Hellwig 2013 整理</footer></div><p><a href="/econ/bm-modern-runs">上一课</a>把可跑的债写成有参数的协调博弈，并留下一个缺口：保险与暂停兑付删掉坏均衡之后，激励问题原样留在场内——被保护的人不再看门。主干课的 <a href="/econ/basel-capital">巴塞尔资本</a>钉过框架：分子吸收损失、分母是风险加权资产、杠杆率与流动性指标做后兜；<a href="/econ/deposit-insurance">存款保险</a>钉过平坦保费等于送出看跌。本课补「理论」二字：资本为什么是恰当的监管工具、要求多少、分母选什么，以及这些选择的代价如何被套利接走。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无关性视角会说：MM 之后资本结构不该影响银行的资产决策，监管资本多此一举。这个论证漏掉的正是上一课的地基：银行负债侧挂着保险与最后贷款人，损失的下尾被外部化给保险基金与纳税人，股东保留上行——资产替代不再由股东自己买单。于是资本的问题分解为三个角色：<strong>吸收</strong>（把亏损顺序写回合同：先吃股权、后动保险基金）；<strong>激励</strong>（让有人替公众看门）；<strong>定价</strong>（安全网的补贴随杠杆上升，资本是对看跌的收费）。三个角色不是并列的三句话，而是同一张资产负债表排序的三种读法。</p><p><span class="marginnote">术语翻译：「资产替代」指股东拿别人的保险去赌——下行亏的是保险基金与纳税人，上行赚的是自己。MM 世界里股东得自己买单，所以没事；安全网一挂，赌性就出来，资本要求就是把账单写回股东头上。</span></p><h3 id="为什么是股本-而不是更准的保险费" tabindex="-1">为什么是股本，而不是更准的保险费 <a class="header-anchor" href="#为什么是股本-而不是更准的保险费" aria-label="Permalink to &quot;为什么是股本，而不是更准的保险费&quot;">​</a></h3><p>事后的风险定价保费需要逐笔计量风险，误差大且滞后；事前的资本要求把约束交还市场的破产威胁——亏损先落到股东头上，股东在事前就有动机管住资产选择。Holmström–Tirole 1997 给了中介版的论证：监督努力不可验证时，外部人只肯把钱交给有自有资金在场的银行——资本是「尽力监督」的可置信押金，没有它，中介连市场的钱都融不到。资本要求因此有两重身份：对监管者是吸收垫，对市场是信用凭证。</p><p><span class="marginnote">Admati–Hellwig 2013 引的历史对照：19 世纪银行股本占比常达两位数；现代百分之几的安全垫，是存款保险与救助网络换来的。评价资本要求的基准是安全网的补贴，不是历史习惯。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监管的形状之争在分母上。<strong>风险加权（RWA）<strong>精细：安全资产低权重、风险资产高权重，但权重出自模型——内部评级给了银行自由度，「把资产在分母上做轻」是协调博弈之外的第二种可操纵结构。<strong>杠杆率</strong>粗糙但模型无关：不看权重，直接对总资产设下限，为模型误差兜底；两者是误差类型的对偶，不是孰优孰劣。第三种形状来自 Kashyap–Rajan–Stein 2008 的</strong>资本保险</strong>：事前交保费、预设的坏状态里兑现成股本——把吸收写成保险合同，绕开事中融资的顺周期。三种工具共享同一个约束：度量误差与套利空间的权衡，谁也没有免费档。</p><p><span class="marginnote">数字实例：同样 100 亿资产，风险权重 20% 时 RWA 为 20 亿，8% 的要求只需 1.6 亿股本；若把这批资产「做」成 10% 权重，要求立刻降到 0.8 亿——分母上省下的全是真金白银的股本，这正是操纵的动机。</span></p>',12)),(A(),o(n,null,{default:t(()=>[l(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NET%5B%22%E5%AE%89%E5%85%A8%E7%BD%91%EF%BC%9A%E4%BF%9D%E9%99%A9%E4%B8%8E%E6%9C%80%E5%90%8E%E8%B4%B7%E6%AC%BE%E4%BA%BA%22%5D%20--%3E%20INC%5B%22%E6%BF%80%E5%8A%B1%E6%89%AD%E6%9B%B2%EF%BC%9A%E4%B8%8B%E8%A1%8C%E5%A4%96%E9%83%A8%E5%8C%96%22%5D%0A%20%20INC%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%EF%BC%9A%E5%90%B8%E6%94%B6%E3%80%81%E6%8A%BC%E9%87%91%E3%80%81%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20CAP%20--%3E%20RW%5B%22RWA%EF%BC%9A%E7%B2%BE%E7%BB%86%E3%80%81%E5%8F%AF%E6%93%8D%E7%BA%B5%22%5D%0A%20%20CAP%20--%3E%20LEV%5B%22%E6%9D%A0%E6%9D%86%E7%8E%87%EF%BC%9A%E7%B2%97%E7%B3%99%E3%80%81%E6%A8%A1%E5%9E%8B%E6%97%A0%E5%85%B3%22%5D%0A%20%20RW%20--%3E%20ARB%5B%22%E5%88%86%E6%AF%8D%E5%8F%98%E8%BD%BB%EF%BC%9A%E5%B7%A5%E5%BA%8F%E5%A4%96%E7%A7%BB%22%5D%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%BD%B1%E5%AD%90%E9%93%B6%E8%A1%8C%22%5D%0A%20%20LEV%20--%3E%20BACK%5B%22%E5%AF%B9%E6%A8%A1%E5%9E%8B%E8%AF%AF%E5%B7%AE%E5%85%9C%E5%BA%95%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("「股本贵」的论证要拆开看。Admati–Hellwig 的要点：股本的"),e("strong",null,"社会"),a("成本远低于银行的"),e("strong",null,"私人"),a("成本——税收盾偏向债务、隐性担保压低债务利率、大机构预期的救助兜底进一步压价；用私人成本反推「资本要求伤经济」，是把补贴当成了成本。要求多高则没有最优点可写：资本越高，吸收与押金越厚；但合规成本推得过高，中介就搬出表内做同样的期限转换而不背资本——这正是下一课的入口，工具的价格在此显形。资本也是主干课定性过的内生货币的数量阀：阀拧的是外部化的下尾，拧得太松，第一课的阈值与激励同时恶化。")],-1)),(A(),o(n,null,{default:t(()=>[l(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E5%A4%9A%E7%94%A8%E8%82%A1%E6%9C%AC%22%5D%20--%3E%20PC%5B%22%E9%93%B6%E8%A1%8C%E7%9A%84%E8%B4%A6%E9%9D%A2%E6%88%90%E6%9C%AC%E6%98%BE%E5%BE%97%E9%AB%98%22%5D%0A%20%20PC%20--%3E%20WHY%7B%22%E4%B8%BA%E4%BB%80%E4%B9%88%E6%98%BE%E5%BE%97%E8%B4%B5%EF%BC%9F%22%7D%0A%20%20WHY%20--%3E%20T1%5B%22%E7%A8%8E%E6%94%B6%E7%9B%BE%E5%81%8F%E5%90%91%E5%80%BA%E5%8A%A1%22%5D%0A%20%20WHY%20--%3E%20T2%5B%22%E9%9A%90%E6%80%A7%E6%8B%85%E4%BF%9D%E5%8E%8B%E4%BD%8E%E5%80%BA%E5%8A%A1%E5%88%A9%E7%8E%87%22%5D%0A%20%20WHY%20--%3E%20T3%5B%22%E6%95%91%E5%8A%A9%E9%A2%84%E6%9C%9F%E8%BF%9B%E4%B8%80%E6%AD%A5%E5%8E%8B%E4%BB%B7%22%5D%0A%20%20T1%20--%3E%20SC%5B%22%E8%82%A1%E6%9C%AC%E7%9A%84%E7%A4%BE%E4%BC%9A%E6%88%90%E6%9C%AC%E8%BF%9C%E4%BD%8E%E4%BA%8E%E7%A7%81%E4%BA%BA%E6%88%90%E6%9C%AC%22%5D%0A%20%20T2%20--%3E%20SC%0A%20%20T3%20--%3E%20SC%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲巴塞尔三版的技术清单，也不展开 2023 年的账面达标悖论——HTM 浮亏与「资本比率达标」并存，说明监管口径与市场口径会分裂，这里只点名。顺周期缓冲的规则设计与影子套利、救助，都只留接口。还有一条要划清：资本充足不是挤兑免疫——第一课的阈值里资本只是移动 \\(\\theta^*\\) 的一个参数；把「资本够了」当成对协调问题的答案，是 2008 年前最贵的误读。</p><p><span class="marginnote">常见误区：把「资本充足」当挤兑免疫。资本只是移动阈值 \\(\\theta^*\\) 的一个参数，协调博弈还在原地；2008 年前不少机构比率达标照样停滚——够不够要对着可跑的债算，不是对着比率算。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资本三职：吸收损失、给监督押金、给安全网定价；保险替代不了任何一职。</li><li>MM 不是资本无关的理由：外部化的下尾才是监管对象。</li><li>RWA 精细但可操纵，杠杆率粗糙但模型无关；资本保险把吸收写成合同。</li><li>股本的社会成本不等于私人成本；补贴常被算成了成本。</li><li>资本要求的影子价格是工序外移：工具的价格在影子课上兑现。</li><li>出处：Holmström–Tirole 1997；Admati–Hellwig 2013；Kashyap–Rajan–Stein 2008；Freixas–Rochet《Microeconomics of Banking》。</li></ul>',5))])}const f=i(p,[["render",m]]);export{T as __pageData,f as default};
